# 프로그램은 하나. 인자로 받은 수만큼 스레드를 띄우고 잠든다.

$ cat Areas.java
public class Areas {
    public static void main(String[] a) throws Exception {
        int n = Integer.parseInt(a[0]);
        Thread[] ts = new Thread[n];
        for (int i = 0; i < n; i++) {
            ts[i] = new Thread(() -> { try { Thread.sleep(20000); } catch (Exception e) {} });
            ts[i].setDaemon(true);
            ts[i].start();
        }
        System.out.println("pid=" + ProcessHandle.current().pid());
        Thread.sleep(20000);
    }
}

# NMT 는 살아 있는 동안 jcmd 로 떠야 한다.
